def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a uniform separator row or column.
    sep = None
    horizontal = False
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            sep, horizontal = r, True
            break
    if sep is None:
        for c in range(w):
            if all(grid[r][c] == grid[0][c] and grid[0][c] != 0 for r in range(h)):
                sep, horizontal = c, False
                break

    if horizontal:
        a, b = grid[:sep], grid[sep + 1:]
        da = sum(x != 0 for row in a for x in row) / (len(a) * w)
        db = sum(x != 0 for row in b for x in row) / (len(b) * w)
        sparse, other = (a, b) if da <= db else (b, a)
    else:
        a = [row[:sep] for row in grid]
        b = [row[sep + 1:] for row in grid]
        da = sum(x != 0 for row in a for x in row) / (h * len(a[0]))
        db = sum(x != 0 for row in b for x in row) / (h * len(b[0]))
        sparse, other = (a, b) if da <= db else (b, a)

    return [[2 if x != 0 and y != 0 else 0 for x, y in zip(sr, orow)]
            for sr, orow in zip(sparse, other)]
